import requests
from flask import Blueprint, request, abort

metrics_bp = Blueprint('metrics', __name__)
ALLOWED_HOSTS = {"https://status.internal.corp", "https://api.internal.corp/health"}

@metrics_bp.route('/proxy', methods=['GET'])
def proxy_metrics():
    url = request.args.get("target")
    # Strict exact-match allowlist check
    if url not in ALLOWED_HOSTS:
   abort(403, description="Host not in allowlist")

    resp = requests.get(url, timeout=3)
    return resp.text

